INSERT INTO equipment (id, name, description, item_type, rarity, cost_gp, weight_lb, weapon_category, damage_dice, damage_type, weapon_properties, weapon_mastery, range_normal, range_long, versatile_damage, ammunition, armor_class, armor_type, dex_bonus_max, strength_requirement, stealth_disadvantage, is_magical, created_at, attunement_requirement) VALUES (276, 'Manual of Bodily Health', 'Study this book to increase your Constitution by 2, to a maximum of 24.', 'wondrous', 'very rare', 50000.0, 5.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025-09-10 15:50:15', NULL);
INSERT INTO equipment (id, name, description, item_type, rarity, cost_gp, weight_lb, weapon_category, damage_dice, damage_type, weapon_properties, weapon_mastery, range_normal, range_long, versatile_damage, ammunition, armor_class, armor_type, dex_bonus_max, strength_requirement, stealth_disadvantage, is_magical, created_at, attunement_requirement) VALUES (285, 'Amulet of Health', 'Your Constitution score is 19 while you wear this amulet. It has no effect on you if your Constitution is already 19 or higher.', 'wondrous item', 'rare', 8000.0, 1.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025-09-12 08:52:39', 'any');
INSERT INTO equipment (id, name, description, item_type, rarity, cost_gp, weight_lb, weapon_category, damage_dice, damage_type, weapon_properties, weapon_mastery, range_normal, range_long, versatile_damage, ammunition, armor_class, armor_type, dex_bonus_max, strength_requirement, stealth_disadvantage, is_magical, created_at, attunement_requirement) VALUES (286, 'Boots of Elvenkind', 'While you wear these boots, your steps make no sound, regardless of the surface you are moving across. You also have advantage on Dexterity (Stealth) checks that rely on moving silently.', 'wondrous item', 'uncommon', 2500.0, 1.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025-09-12 08:52:45', NULL);
INSERT INTO equipment (id, name, description, item_type, rarity, cost_gp, weight_lb, weapon_category, damage_dice, damage_type, weapon_properties, weapon_mastery, range_normal, range_long, versatile_damage, ammunition, armor_class, armor_type, dex_bonus_max, strength_requirement, stealth_disadvantage, is_magical, created_at, attunement_requirement) VALUES (287, 'Gloves of Thievery', 'These gloves are invisible while worn. While wearing them, you gain a +5 bonus to Dexterity (Sleight of Hand) checks and Dexterity checks made to pick locks.', 'wondrous item', 'uncommon', 5000.0, 1.0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025-09-12 08:52:55', NULL);
INSERT INTO equipment (id, name, description, item_type, rarity, cost_gp, weight_lb, weapon_category, damage_dice, damage_type, weapon_properties, weapon_mastery, range_normal, range_long, versatile_damage, ammunition, armor_class, armor_type, dex_bonus_max, strength_requirement, stealth_disadvantage, is_magical, created_at, attunement_requirement) VALUES (288, 'Ring of Evasion', 'This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. When you fail a Dexterity saving throw while wearing it, you can use your reaction to expend 1 charge to succeed on that saving throw instead.', 'wondrous item', 'rare', 5000.0, 0.1, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, '2025-09-12 08:53:01', 'any');
INSERT INTO weapon_masteries (id, name, trigger_condition, description, requires_save, save_ability, save_dc_formula, damage_formula, special_effects) VALUES (1, 'Cleave', 'on_hit', 'If you hit a creature with a melee attack roll using this weapon, you can make a melee attack roll with the weapon against a second creature within 5 feet of the first that is also within your reach. On a hit, the second creature takes the weapon''s damage, but don''t add your ability modifier to that damage unless that modifier is negative. You can make this extra attack only once per turn.', 0, NULL, NULL, 'weapon_damage_no_modifier', 'extra_attack_adjacent');
INSERT INTO weapon_masteries (id, name, trigger_condition, description, requires_save, save_ability, save_dc_formula, damage_formula, special_effects) VALUES (2, 'Graze', 'on_miss', 'If your attack roll with this weapon misses a creature, you can deal damage to that creature equal to the ability modifier you used to make the attack roll. This damage is the same type dealt by the weapon, and the damage can be increased only by increasing the ability modifier.', 0, NULL, NULL, 'ability_modifier', 'damage_on_miss');
INSERT INTO weapon_masteries (id, name, trigger_condition, description, requires_save, save_ability, save_dc_formula, damage_formula, special_effects) VALUES (3, 'Nick', 'on_hit', 'When you make the extra attack of the Light property, you can make it as part of the Attack action instead of as a Bonus Action. You can make this extra attack only once per turn.', 0, NULL, NULL, NULL, 'light_attack_as_action');
INSERT INTO weapon_masteries (id, name, trigger_condition, description, requires_save, save_ability, save_dc_formula, damage_formula, special_effects) VALUES (4, 'Push', 'on_hit', 'If you hit a creature with this weapon, you can push the creature up to 10 feet straight away from yourself if it is Large or smaller.', 0, NULL, NULL, NULL, 'push_10_feet');
INSERT INTO weapon_masteries (id, name, trigger_condition, description, requires_save, save_ability, save_dc_formula, damage_formula, special_effects) VALUES (5, 'Sap', 'on_hit', 'If you hit a creature with this weapon, that creature has Disadvantage on its next attack roll before the start of your next turn.', 0, NULL, NULL, NULL, 'disadvantage_next_attack');
INSERT INTO weapon_masteries (id, name, trigger_condition, description, requires_save, save_ability, save_dc_formula, damage_formula, special_effects) VALUES (6, 'Slow', 'on_hit', 'If you hit a creature with this weapon and deal damage to it, you can reduce its Speed by 10 feet until the start of your next turn. If the creature is hit more than once by weapons that have this property, the Speed reduction doesn''t exceed 10 feet.', 0, NULL, NULL, NULL, 'reduce_speed_10');
INSERT INTO weapon_masteries (id, name, trigger_condition, description, requires_save, save_ability, save_dc_formula, damage_formula, special_effects) VALUES (7, 'Topple', 'on_hit', 'If you hit a creature with this weapon, you can force the creature to make a Constitution saving throw (DC 8 plus the ability modifier used to make the attack roll and your Proficiency Bonus). On a failed save, the creature has the Prone condition.', 1, 'Constitution', '8 + ability_modifier + proficiency_bonus', NULL, 'prone_on_failed_save');
INSERT INTO weapon_masteries (id, name, trigger_condition, description, requires_save, save_ability, save_dc_formula, damage_formula, special_effects) VALUES (8, 'Vex', 'on_hit', 'If you hit a creature with this weapon and deal damage to the creature, you have Advantage on your next attack roll against that creature before the end of your next turn.', 0, NULL, NULL, NULL, 'advantage_next_attack');
